    int LOWEST_PRECEDENCE = Integer.MAX_VALUE;

    /**
     * 获取当前对象的顺序值。
     * <p>值越大，优先级越低。
     * 最小值对应最高优先级，类似于
     * Servlet 的 {@code load-on-startup}。
     * <p>顺序值相同时，
